UPDATE diagram_canvas_state
SET current_xml = #{currentXml},
    summary = #{summary},
    analysis_json = #{analysisJson},
    version = version + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE diagram_id = #{diagramId}
  AND user_id = #{userId}
  AND version = #{version}

mapper.select:
SELECT COUNT(1)
FROM diagram_canvas_state
WHERE diagram_id = #{diagramId}
  AND user_id = #{userId}

SELECT COUNT(1)
FROM diagram
WHERE id = #{diagramId}

mapper.update:
UPDATE diagram
SET title = #{title},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{diagramId}
  AND user_id = #{userId}
  AND deleted = 0

UPDATE diagram
SET deleted = 1,
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{diagramId}
  AND user_id = #{userId}
  AND deleted = 0
